(function(){let started=false;window.AOS={init:function(options){if(started)return;started=true;const nodes=[...document.querySelectorAll('[data-aos]')];if(!('IntersectionObserver'in window)){nodes.forEach(n=>n.classList.add('aos-animate'));return}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('aos-animate');if(!(options&&options.once===false))observer.unobserve(entry.target)}}),{threshold:.1});nodes.forEach(n=>observer.observe(n))}}})();
